// Each language's name for itself, for the choice in Settings.
const LEMBAS_LANGS = {"cs": "Čeština", "de": "Deutsch", "en": "English", "es": "Español", "fr": "Français", "hu": "Magyar", "it": "Italiano", "pl": "Polski", "sk": "Slovenčina"}

// What the system's language gives, and what was chosen here instead ("" for the system's).
const LEMBAS_SYSTEM_LANG = (() => {
  const code = String(navigator.language || "").slice(0, 2).toLowerCase()
  return Object.prototype.hasOwnProperty.call(LEMBAS_I18N, code) ? code : "en"
})()
// Settings' choice: "" for the account's language (as /me last said it), "system", or a code.
const LEMBAS_CHOICE = (() => {
  try {
    return localStorage.getItem("lembas.language") || ""
  } catch {
    return ""
  }
})()
const LEMBAS_CHOSEN_LANG = (() => {
  const has = (code) => Object.prototype.hasOwnProperty.call(LEMBAS_LANGS, code)
  if (LEMBAS_CHOICE === "system") return ""
  if (has(LEMBAS_CHOICE)) return LEMBAS_CHOICE
  let account = ""
  try {
    account = localStorage.getItem("lembas.account-language") || ""
  } catch {}
  return has(account) ? account : ""
})()
const LEMBAS_LANG = LEMBAS_CHOSEN_LANG || LEMBAS_SYSTEM_LANG
document.documentElement.lang = LEMBAS_LANG

function t(text, fields) {
  const key = String(text).replace(/\s+/g, " ").trim()
  const table = LEMBAS_I18N[LEMBAS_LANG] || {}
  const out = Object.prototype.hasOwnProperty.call(table, key) ? table[key] : key
  if (!fields) return out
  return out.replace(/%\((\w+)\)s/g, (all, name) =>
    Object.prototype.hasOwnProperty.call(fields, name) ? String(fields[name]) : all)
}

function translatePage() {
  for (const el of document.querySelectorAll("[data-i18n]")) el.textContent = t(el.textContent)
  for (const attr of ["title", "aria-label", "placeholder"]) {
    for (const el of document.querySelectorAll(`[data-i18n-${attr}]`)) {
      el.setAttribute(attr, t(el.getAttribute(attr)))
    }
  }
}
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", translatePage)
else translatePage()
